// Biomedical Debate Practice Test 3. Original questions written for Valus on the 2026–27 resolution,
// "Limited healthcare resources should be allocated to patients with the greatest likelihood of
// long-term survival." Slightly harder than the sample items, covering material not used in Tests 1–2.
import {q, mix} from './q.js';
const LEVY='Levy, Breaking the Age Code (2022)', BH='Bognar & Hirose, The Ethics of Health Care Rationing', EMAN='Emanuel et al., NEJM (2020)', PERSAD='Persad, Wertheimer & Emanuel, The Lancet (2009)', OPTN='Organ Procurement and Transplantation Network';
const SCAR='Scarcity and Levels of Allocation', ETH='Ethical Theories and Principles', CRIT='Allocation Criteria and Frameworks', CASE='Real-World Allocation Cases', AGE='Aging, Longevity and Equity';

export default {
 id:'biomedical-debate-3',
 event:'Biomedical Debate',
 title:'Practice Test 3',
 subtitle:'Round One test simulation on the 2026–27 resolution',
 minutes:60,
 sources:'Levy’s Breaking the Age Code, Bognar and Hirose’s The Ethics of Health Care Rationing and published allocation frameworks',
 plan:[{area:'Resolution: Allocating Limited Healthcare Resources',weight:100,topics:[SCAR,ETH,CRIT,CASE,AGE]}],
 questions:mix([
  q(SCAR,'Giving every patient a smaller amount of a scarce resource than would be ideal is called rationing by:','Dilution',['Deflection','Deterrence','Denial'],'A','Dilution spreads a resource thinly, such as fractional vaccine doses; it can help more people but may reduce benefit to each.',BH),
  q(SCAR,'In mass casualty triage, a patient tagged “expectant” (black) is one who:','Is unlikely to survive',['Needs care within minutes','Can safely wait hours','Has only minor injuries'],'B','Expectant patients receive comfort care so scarce resources go to those who can be saved; they are reassessed as resources allow.',BH),
  q(SCAR,'The word “triage” comes from a French verb meaning:','To sort',['To heal','To wait','To save'],'C','Triage sorts patients by urgency and likely benefit; it began on battlefields and is now used in emergency departments.',BH),
  q(SCAR,'In January 2022, the American Red Cross declared its first-ever national:','Blood crisis',['Nurse strike','Vaccine recall','Ventilator recall'],'D','Donations fell during the pandemic, forcing hospitals to choose which patients received transfusions.',BH),
  q(SCAR,'On the surge continuum, care that no longer meets usual standards but aims for the best outcome for the population is:','Crisis capacity',['Conventional capacity','Contingency capacity','Routine capacity'],'A','Crisis capacity shifts the goal from each individual patient to the community, which is when allocation rules are activated.',EMAN),
  q(SCAR,'Which state is known for legally mandated nurse-to-patient ratios in hospitals?','California',['Texas','Florida','Michigan'],'B','Staffing ratios address relative scarcity: beds may exist, but they cannot be used safely without enough nurses.',BH),
  q(SCAR,'In 2009, which body issued national guidance for establishing crisis standards of care?','The Institute of Medicine',['The World Bank','The Joint Commission','The UK’s NICE board'],'C','The IOM (now the National Academy of Medicine) urged states to plan fair, transparent crisis standards before disasters.',EMAN),
  q(SCAR,'According to HRSA, about how many people in the U.S. die each day waiting for an organ transplant?','17',['2','170','1,700'],'D','More than 100,000 people are on the waiting list, and organ supply falls far short of need.',OPTN),
  q(ETH,'In “Should the Numbers Count?” (1977), John Taurek argued that when choosing between saving one or five strangers:','Each person deserves an equal chance',['The five must always be saved','The youngest must be saved','The doctor should simply decide'],'A','Taurek suggested flipping a coin, challenging the utilitarian view that saving more lives is always required.',BH),
  q(ETH,'Which objection says strict equality could be reached by making the better-off worse off with no gain to anyone?','The leveling-down objection',['The aggregation problem','The rule of rescue','The fair innings argument'],'B','Critics such as Derek Parfit argue that equality achieved only by harming some people is not an improvement.',BH),
  q(ETH,'Rawls’s difference principle allows inequalities only if they:','Benefit the least advantaged',['Increase total welfare','Reward individual effort','Arise from a fair lottery'],'C','Rawls held that unequal distributions are just only when they improve the position of the worst-off group.',BH),
  q(ETH,'Rawls criticized utilitarianism for ignoring the:','Separateness of persons',['Rule of rescue','Fair innings ideal','Value of market prices'],'D','Adding up benefits across people treats them like one big person, so one person’s loss can be “paid for” by others’ gains.',BH),
  q(ETH,'Norman Daniels argued that health care is morally special because it protects:','Fair equality of opportunity',['Maximum total happiness','Free market choice','Religious freedom'],'A','Disease limits the range of life plans open to a person, so meeting health needs supports equal opportunity.',BH),
  q(ETH,'Which theory judges allocation by the character of the decision-maker, such as compassion and fairness?','Virtue ethics',['Utilitarianism','Libertarianism','Egalitarianism'],'B','Virtue ethics asks what a good clinician or policymaker would do, rather than applying a single rule.',BH),
  q(ETH,'The capability approach of Amartya Sen and Martha Nussbaum focuses on:','What people are able to do and be',['How many QALYs a program yields','Each person’s ability to pay','The order in which people arrive'],'C','It measures well-being by real freedoms, such as being able to move, work and take part in community life.',BH),
  q(ETH,'Luck egalitarians may give lower priority to patients whose illness resulted from:','Their own voluntary choices',['Their inherited genetic makeup','Bad luck at the time of birth','An accident while at work'],'D','This responsibility-based view is debated, since choices like smoking are shaped by addiction and social conditions.',BH),
  q(ETH,'The principle of nonmaleficence means:','Avoid causing harm',['Respect patient choices','Distribute resources fairly','Always extend life'],'A','Nonmaleficence (“first, do no harm”) is one of Beauchamp and Childress’s four principles of biomedical ethics.',BH),
  q(CRIT,'A treatment gives 10 years of life at a quality weight of 0.7. How many QALYs does it produce?','7',['3','10','17'],'B','QALYs = years × quality weight = 10 × 0.7 = 7. Perfect health has a weight of 1 and death a weight of 0.',BH),
  q(CRIT,'A new drug costs $50,000 more than standard care and adds 2 QALYs. What is its incremental cost-effectiveness ratio?','$25,000 per QALY',['$100,000 per QALY','$48,000 per QALY','$52,000 per QALY'],'C','ICER = added cost ÷ added QALYs = $50,000 ÷ 2 = $25,000 per QALY gained.',BH),
  q(CRIT,'Which method asks people how many years of full health they would accept instead of more years in worse health?','Time trade-off',['Standard gamble','Visual analog scale','Willingness to pay'],'D','If someone would trade 10 years with a condition for 8 healthy years, the condition’s weight is 0.8.',BH),
  q(CRIT,'The standard gamble estimates quality weights by asking people about:','Risking death for a cure',['Paying for treatment','Waiting time for surgery','Years spent in school'],'A','People choose between a certain health state and a gamble with a chance of full health or death.',BH),
  q(CRIT,'Which questionnaire rates mobility, self-care, usual activities, pain and anxiety to calculate quality weights?','EQ-5D',['APACHE','SOFA','MELD'],'B','The EQ-5D’s five dimensions produce a health profile that is converted into a utility score for QALYs.',BH),
  q(CRIT,'Which ICU scoring system predicts hospital mortality from acute physiology and chronic health?','APACHE II',['EQ-5D-5L','KDPI score','EPTS score'],'C','APACHE II uses vital signs, lab values, age and chronic illness to estimate the risk of death in critically ill patients.',EMAN),
  q(CRIT,'Which index scores comorbid conditions to predict 10-year mortality?','Charlson Comorbidity Index',['Glasgow Coma Scale','Apgar scoring system','Braden pressure ulcer scale'],'D','Survival-based allocation could use such indexes, but critics say they penalize chronic illness and disability.',EMAN),
  q(CRIT,'The “disability paradox” refers to the finding that many people with serious disabilities:','Report good quality of life',['Report the worst quality of life','Refuse all medical care','Live longer than average'],'A','Outsiders often underrate life with disability, which can bias quality weights used in allocation.',BH),
  q(CRIT,'Which U.S. law bars PCORI from using cost per QALY as a threshold?','The Affordable Care Act',['The Social Security Act','The ADA of 1990','The Public Health Act'],'B','Congress worried that QALY thresholds could devalue the lives of older and disabled people.',BH),
  q(CRIT,'How does ICER’s “equal value of life-years gained” (evLYG) differ from the QALY?','It values added life equally for all',['It counts only deaths averted','It ignores treatment costs entirely','It weights younger lives more'],'C','evLYG gives every added year of life a full weight of 1, regardless of disability, answering a major QALY critique.',BH),
  q(CRIT,'Older WHO-CHOICE guidance called an intervention “very cost-effective” if its cost per DALY averted was below:','1× GDP per capita',['10× GDP per capita','$1 million','$100'],'D','The guidance used 1× GDP per capita for “very cost-effective” and 3× for “cost-effective”; the WHO later moved away from fixed thresholds.',BH),
  q(CRIT,'In White and Lo’s multi-principle triage framework, points were added to the SOFA score for:','Severe comorbidities',['Inability to pay','Low-status job titles','Late hospital arrival'],'A','The framework combined short-term survival (SOFA) with near-term life expectancy, with life stage as a tiebreaker.',EMAN),
  q(CRIT,'New York’s 2015 ventilator allocation guidelines based triage mainly on:','Short-term survival',['Long-term life expectancy','Age alone','Social worth'],'B','New York deliberately avoided long-term survival and age criteria, a useful contrast for negative teams.',EMAN),
  q(CRIT,'Under New York’s 2015 guidelines, ventilated patients were reassessed at which time points?','48 and 120 hours',['6 and 12 hours','1 and 2 weeks','30 and 60 days'],'C','Time-limited trials let clinicians reallocate ventilators from patients who are not improving.',EMAN),
  q(CASE,'Shana Alexander’s 1962 Life magazine article exposed:','Seattle’s dialysis panel',['Oregon’s priority list','Italy’s ICU age limits','NICE’s cost limits'],'D','The article revealed that lay members judged patients’ social worth, sparking the field of bioethics.',BH),
  q(CASE,'After the Seattle dialysis controversy, what 1972 change made dialysis widely available in the U.S.?','Medicare coverage for kidney failure',['A ban on home dialysis machines','A national dialysis lottery','A private insurance mandate'],'A','The End-Stage Renal Disease program removed most selection by covering dialysis for nearly all Americans with kidney failure.',BH),
  q(CASE,'In WWII North Africa, scarce penicillin reportedly went to soldiers with gonorrhea before the badly wounded. Which principle does this show?','Social utility',['Sickest first','Youngest first','Equal chance'],'B','Treated soldiers could return to duty quickly, so they were prioritized for their usefulness to the war effort.',BH),
  q(CASE,'In 2014, the scarce experimental Ebola drug ZMapp was first given to:','Two American aid workers',['Children in Liberia','The oldest patients','Patients picked by lottery'],'C','Critics asked why Westerners received the first doses while thousands of West Africans were infected.',BH),
  q(CASE,'During the 2009 H1N1 pandemic, early U.S. vaccine priority included pregnant women and:','Children and young adults',['Adults over 80 only','All prison employees','Professional athletes'],'D','H1N1 hit young people hard, so priority followed risk rather than age alone, unlike seasonal flu.',BH),
  q(CASE,'In 2004, contamination at one manufacturer cut the U.S. flu vaccine supply nearly in half. What did the CDC do?','Prioritized high-risk groups',['Canceled the flu season','Held a national lottery','Sold doses at auction'],'A','Priority went to older adults, young children, people with chronic illness and health care workers.',BH),
  q(CASE,'When the hepatitis C drug sofosbuvir launched at about $84,000, many state Medicaid programs:','Limited it to the sickest',['Covered it for every patient','Banned the drug completely','Assigned it by lottery'],'B','Restricting the cure to patients with advanced liver damage was later challenged, and most limits were relaxed.',BH),
  q(CASE,'Novartis’s 2020 program giving away free doses of the gene therapy Zolgensma was criticized for using:','A lottery',['Age limits','Social worth','Waiting time'],'C','Critics said a lottery for a life-saving infant therapy turned a medical decision into a game of chance.',BH),
  q(CASE,'Baseball star Mickey Mantle’s 1995 liver transplant raised public concern about:','Fame and past alcohol use',['Use of animal organs','Cost of anti-rejection drugs','Paid organ donation'],'D','He received a liver within days; officials said medical urgency drove the decision, but the case fueled debate.',OPTN),
  q(CASE,'Which UK fund was created in 2011 to pay for cancer drugs that NICE had not approved?','The Cancer Drugs Fund',['The Postcode Fund','The NHS Lottery Fund','The QALY Reserve Fund'],'A','The fund showed political pressure to bypass cost-effectiveness limits for high-profile illnesses.',BH),
  q(CASE,'In Chaoulli v. Quebec (2005), Canada’s Supreme Court ruled on:','Private insurance and long waits',['Legal sales of kidneys','Assisted dying laws','Vaccine mandates for staff'],'B','The court struck down Quebec’s ban on private insurance for services with unreasonable public waiting times.',BH),
  q(CASE,'New Zealand’s PHARMAC is known for:','Buying drugs within a fixed budget',['Running all public hospitals','Approving drugs as safe','Training new pharmacists'],'C','PHARMAC negotiates prices and chooses which drugs to fund, an example of explicit national rationing.',BH),
  q(AGE,'Levy’s “ABC method” for fighting ageism stands for:','Awareness, Blame, Challenge',['Age, Body, Care','Attitude, Belief, Change','Ask, Build, Commit'],'D','Levy urges people to notice age stereotypes, place blame on ageism rather than aging, and challenge negative beliefs.',LEVY),
  q(AGE,'Levy found that carriers of the APOE ε4 dementia gene who held positive age beliefs were:','Less likely to develop dementia',['More likely to develop dementia','Unaffected by their beliefs','Faster to lose hearing'],'A','Age beliefs appeared to buffer genetic risk, suggesting that prognosis is not fixed by biology alone.',LEVY),
  q(AGE,'Levy’s 7.5-year longevity finding came from which long-term study?','The Ohio Longitudinal Study',['The Framingham Heart Study','The Nurses’ Health Study','The Harvard Grant Study'],'B','The Ohio Longitudinal Study of Aging and Retirement followed adults for over two decades.',LEVY),
  q(AGE,'Gruenberg’s “failures of success” view predicts that medical advances lead to:','More years lived with disability',['Compression of morbidity','Shorter average lifespans','Fewer chronic diseases'],'C','It contrasts with Fries’s view that illness can be compressed into a short period near the end of life.',LEVY),
  q(AGE,'Chetty et al. (2016) found that U.S. life expectancy for men in the richest and poorest 1% differed by about:','15 years',['1 year','5 years','30 years'],'D','Since life expectancy tracks income, negative teams argue survival-based allocation favors the wealthy.',BH),
  q(AGE,'Which 1975 U.S. law prohibits age discrimination in federally funded programs?','The Age Discrimination Act',['The Older Americans Act','The Organ Transplant Act','The Social Security Act'],'A','Crisis plans that exclude patients by age alone may conflict with this law, which covers most hospitals.',BH),
  q(AGE,'The U.S. Census Bureau projects older adults will outnumber children for the first time around:','2034',['2010','2075','2100'],'B','An aging population increases demand for scarce resources, raising questions about age-based allocation.',LEVY)
 ],5707)
};
